    def longestPalindrome(self, s: str, t: str) -> int:
        ns, nt = len(s), len(t)

        # best_s[a]: length of longest palindromic substring of s starting at index a
        best_s = [0] * (ns + 1)
        for a in range(ns):
            for b in range(a, ns):
                sub = s[a:b+1]
                if sub == sub[::-1]:
                    if b - a + 1 > best_s[a]:
                        best_s[a] = b - a + 1

        # best_t_end[d]: length of longest palindromic substring of t ending at index d
        best_t_end = [0] * nt
        for d in range(nt):
            for c in range(d + 1):
                sub = t[c:d+1]
                if sub == sub[::-1]:
                    if d - c + 1 > best_t_end[d]:
                        best_t_end[d] = d - c + 1

        # Pure-s or pure-t cases
        ans = 0
        if ns > 0:
            ans = max(ans, max(best_s))
        if nt > 0:
            ans = max(ans, max(best_t_end))

        # Try all (a, d) pairs as outermost matched indices
        for a in range(ns):
            for d in range(nt):
                # Find max matching pairs from outside-in
                k = 0
                while a + k < ns and d - k >= 0 and s[a + k] == t[d - k]:
                    k += 1
